const WOODS = new Set(["oak", "spruce", "birch", "jungle", "acacia", "dark_oak", "mangrove", "cherry", "bamboo", "crimson", "warped", "pale_oak"]);
/** A material by any name ("deepslate_tiles", "deepslate_tile", "spruce", "stone_brick_stairs") -> its forms. */
export function materialOf(name) {
  let n = strip(name).replace(/_(stairs|slab|wall)$/, "");
  n = n.replace(/^(waxed_)?(exposed_|weathered_|oxidized_)?copper(_block)?$/, (_, w = "", e = "") => `${w}${e}cut_copper`);   // only cut copper has stairs and slabs
  const full = { quartz: "quartz_block", purpur: "purpur_block", smooth_quartz: "smooth_quartz" }[n] || (WOODS.has(n) ? `${n}_planks` : /(brick|tile)$/.test(n) ? `${n}s` : n);
  let p = n.replace(/_planks$/, "").replace(/(brick|tile)s$/, "$1").replace(/^(quartz|purpur)_block$/, "$1");
  return { prefix: p, full: n === p ? full : n, stairs: `${p}_stairs`, slab: `${p}_slab`, wall: `${p}_wall` };
}
/** Materials that have no stairs or slab forms (a roof of them would place invalid blocks). */
