  { name: "pyramid", footprint: [37, 9, 46, 17], style: "pyramid", o: { y: 7, pitch: 1, material: "polished_granite", eave: "polished_granite", ridge: "slab", overhang: 1, keep: [{ from: [41, 6, 12], to: [42, 15, 13] }] } },
