  { name: "boarding house", footprint: [49, 9, 58, 16], style: "gable", o: { y: 12, pitch: 1, ridgeAxis: "x", material: "tuff_brick", eave: "tuff_brick", ridge: "slab", verge: "stripped_oak_log", overhang: { north: 1, south: 1, east: 0, west: 0 }, keep: [{ from: [49, 6, 12], to: [50, 20, 13] }], materialAt: ({ full }) => (full ? "polished_tuff" : null) } },
