  { name: "smokehouse", footprint: [61, 12, 65, 16], style: "gable", o: { y: 5, pitch: 1.5, ridgeAxis: "z", material: "blackstone", eave: "blackstone", ridge: "slab", verge: "spruce", overhang: { north: 1, south: 1, east: 1, west: 0 }, keep: [{ from: [63, 5, 17], to: [63, 15, 17] }] } },
