  { name: "bungalow", footprint: [85, 7, 94, 17], style: "gable", o: { y: 7, pitch: 0.5, ridgeAxis: "z", front: "north", material: { mix: [["oxidized_cut_copper", 70], ["weathered_cut_copper", 30]] }, eave: "oxidized_cut_copper", ridge: "slab", verge: "quartz", overhang: { north: 1, south: 1, east: 0, west: 0 }, keep: [{ from: [85, 6, 13], to: [86, 20, 14] }] } },
